      "why_it_applies": "Wrestling baby / public or family competence; wants capable parent identity with visible proof.",
      "evidence_refs": ["pain_points[5]", "exact_vocabulary[wrestling a rolling baby at 2 a.m.]"],
      "label": "DERIVED"
    },
    {
      "currency_id": "RELATIONAL_EQUITY",
      "why_it_applies": "Neither of us is sleeping; household becomes shift work.",
      "evidence_refs": ["pain_points[2]"],
      "label": "DERIVED"
    },
